SELECT MODEL_ID AS "modelId", MODEL_CODE AS "modelCode", MODEL_NAME AS "modelName", MODEL_TYPE AS "modelType", MODEL_FORMULA AS "modelFormula", MODEL_FORMULA AS "formula", MODEL_DESCRIPTION AS "modelDescription", MODEL_DESCRIPTION AS "description", APPLICABLE_SCENARIO AS "applicableScenario", INDUSTRY AS "industry", ALGORITHM AS "algorithm", ACCURACY_SCORE AS "accuracyScore", ACCURACY_SCORE AS "accuracy", IS_ENABLED AS "isEnabled", CREATE_TIME AS "createTime" FROM TBL_COST_MODEL WHERE 1 = 1
AND BOOK_ID = #{bookId}
AND TENANT_ID = #{tenantId}
AND MODEL_CODE LIKE '%' || #{modelCode} || '%'
AND MODEL_NAME LIKE '%' || #{modelName} || '%'
AND MODEL_TYPE = #{modelType}
AND INDUSTRY = #{industry}
AND IS_ENABLED = #{isEnabled}
ORDER BY ACCURACY_SCORE DESC, CREATE_TIME DESC OFFSET #{offset} ROWS FETCH NEXT #{pageSize} ROWS ONLY

SELECT COUNT(1)
FROM TBL_COST_MODEL
WHERE 1 = 1

      AND BOOK_ID = #{bookId}


      AND TENANT_ID = #{tenantId}


      AND MODEL_CODE LIKE '%' || #{modelCode} || '%'


      AND MODEL_NAME LIKE '%' || #{modelName} || '%'


      AND MODEL_TYPE = #{modelType}


      AND INDUSTRY = #{industry}


      AND IS_ENABLED = #{isEnabled}

SELECT COUNT(1)
FROM TBL_COST_MODEL
WHERE MODEL_CODE = #{modelCode}
  AND BOOK_ID = #{bookId}
  AND TENANT_ID = #{tenantId}

      AND MODEL_ID != #{modelId}
